import {aiSources,isCourseContext,isArticleContext,materials,contextName,contextFor,blockedReason,readable,LIMITS} from './model.js';
import {esc,icon,btn,ibtn,link,notice} from './ui.js';
export function panel(s,route){
 const current=contextFor(route),active=s.context,chat=s.chats[active]||[],hardBlock=blockedReason(s,current==='test'?'test':active),author=active==='author',article=isArticleContext(active),course=isCourseContext(active),general=['catalog','knowledge'].includes(active);
 const unsupported=['video','scorm','file'].includes(active),canFindRelated=current!=='test'&&unsupported&&!['module-off','no-role','quota','external-denied'].includes(s.scenario);
 const starters=article?btn('Объяснить этот материал','quick-understand')+btn('Потренироваться','quick-practice'):course?btn('Разобраться в теме','quick-understand')+btn('Выбрать материал курса','choose-course-material'):btn('Найти материал','quick-find')+btn('Разобраться в теме','quick-understand')+btn('Потренироваться','quick-practice');
 const label=general?'Область поиска: доступные материалы':course?'Обсуждаем курс':'Обсуждаем';
 return '<div class="assistant-head"><h2>Skillaz AI</h2><span class="grow"></span>'+(!author?btn('Новый чат','new-chat','tertiary'):'')+ibtn('clock','history','История обсуждений')+ibtn('cross-outlined','close-panel','Закрыть помощника')+'</div>'+
 '<div class="assistant-context"><span class="muted small">'+(author?'Помощник автора':label)+'</span>'+(!general?'<strong>'+esc(contextName(active))+'</strong>':'')+
 (current!==active?'<div class="context-change"><p class="small muted">Вы открыли «'+esc(contextName(current))+'».</p>'+btn(isCourseContext(current)?'Обсудить этот курс':['catalog','knowledge'].includes(current)?'Искать в доступных материалах':'Обсудить этот материал','switch-context','tertiary')+'</div>':'')+'</div>'+
 '<div class="assistant-log" aria-live="polite">'+(hardBlock?notice(hardBlock,s.scenario==='model-error'?'error':'')+(canFindRelated?btn('Найти материалы по теме','find-related','secondary'):current!=='test'&&['revoked','unpublished','external-denied'].includes(s.scenario)?btn('Выбрать другой источник','choose-other-source','secondary'):''):'')+
 (author?'<div class="assistant-message"><p>Помогу собрать новый курс из материалов.</p>'+btn('Продолжить подготовку','resume-author','secondary')+'</div>':!chat.length&&!hardBlock&&!s.topicPrompt?'<div class="assistant-welcome"><h3>Чем помочь с обучением?</h3><div class="quick-questions">'+starters+'</div></div>':'')+
 (!hardBlock?chat.map((m,i)=>message(s,m,i)).join(''):chat.length?'<p class="hint">История сохранена. Недоступные фрагменты не отображаются.</p>':'')+
 (s.topicPrompt&&!hardBlock?'<div class="topic-prompt"><p>'+esc(s.topicPrompt)+'</p>'+(course?'<div class="mt">'+btn('Выбрать материал курса','choose-course-material','secondary')+'</div>':'')+'</div>':'')+
 (s.sending?'<div class="row muted"><span class="spinner"></span>Ищем в доступных материалах…</div>':'')+'</div>'+
 '<form id="chat-form" class="composer"><label class="sr-only" for="question">Вопрос помощнику</label><textarea id="question" rows="2" maxlength="'+LIMITS.message+'" placeholder="'+(s.topicPrompt?'Например: когда нужно передавать обращение эксперту?':'Задайте вопрос…')+'" '+(hardBlock||author?'disabled':'')+'>'+esc(s.drafts[active]||'')+'</textarea><div class="row between"><span class="hint">'+(author?'Работа с курсом — в редакторе':'Ответы по доступным материалам')+'</span><button class="send-button" type="submit" aria-label="Отправить сообщение" '+(hardBlock||author||s.sending||!s.drafts[active]?.trim()?'disabled':'')+'>'+icon('arrow-right')+'</button></div><div class="field-error" id="question-error"></div></form>';
}
function message(s,m,i){if(m.role==='user')return `<div class="user-message">${esc(m.text)}</div>`;const refs=(m.refs||[]).map(id=>materials.find(x=>x.id===id));if(refs.some(r=>!readable(r,s)||!aiSources(s,'catalog').some(a=>a.id===r.id)))return notice('Фрагмент скрыт: доступ к источнику изменился.');return `<div class="assistant-message" data-message="${i}">${m.kind==='example'?'<span class="tag mb">Учебный пример</span>':''}${m.kind==='practice'?'<span class="tag mb">Тренировка · следующий этап</span>':''}<p>${esc(m.text)}</p>${m.kind==='error'?btn('Повторить запрос','retry-chat','secondary'):''}${m.kind==='search'?refs.map(r=>`<div class="source-card"><span class="hint">${r.kind}</span>${link(esc(r.name),r.route,'source-title')}<p class="small muted">${esc(r.section)}</p>${link('Открыть материал '+icon('arrow-right'),r.route,'link')}</div>`).join(''):refs.length?`<div class="sources">${refs.map(r=>`<details><summary>${icon('book')} ${esc(r.name)}</summary><blockquote>${esc(r.body)}</blockquote>${link('Открыть раздел «'+esc(r.section)+'»',r.route+(r.route.includes('?')?'&':'?')+'focus=source-fragment','link')}</details>`).join('')}</div>`:''}${m.kind==='expand'?btn('Искать в доступных материалах','expand-search','secondary'):''}${m.kind==='clarify'?`<div class="quick-questions">${btn('Передать эксперту','quick-find')}${btn('Сообщить статус','quick-status')}</div>`:''}${m.kind==='explain'?`<div class="message-actions">${btn('Объяснить ещё проще','quick-explain','tertiary')}${btn('Привести пример','quick-example','tertiary')}${btn('Потренироваться','quick-practice','tertiary')}</div>`:''}${m.kind==='search'?btn('Не подходит','quick-clarify','tertiary'):''}${m.kind==='practice'?practice(m,i):''}</div>`;}
function practice(m,i){return `${m.hint?notice('Подумайте о ситуации, уже выполненных действиях и конкретном вопросе эксперту.'):btn('Подсказка','practice-hint','tertiary',`data-index="${i}"`)}${m.attempt?`<div class="practice-answer"><span class="small muted">Ваш ответ</span><p>${esc(m.attempt.text)}</p></div><p class="mt"><b>${m.attempt.complete?'Все необходимые сведения есть.':'Есть что дополнить.'}</b> ${esc(m.attempt.feedback)}</p><p class="hint mt">Неформальная тренировка · следующий этап развития. Не меняет оценку и прогресс курса.</p><div class="row wrap mt">${btn('Попробовать ещё','practice-retry','',`data-index="${i}"`)}${btn('Другая ситуация','quick-practice','tertiary')}${link('К материалу','/learning/play/101?item=expert','link')}</div>`:`<label class="field mt"><span class="muted">Ваш ответ</span><textarea aria-label="Ответ на тренировку" data-practice="${i}" placeholder="Какие сведения вы передадите?"></textarea></label><div class="field-error" id="practice-error-${i}"></div>${btn('Проверить ответ','practice-submit','secondary',`data-index="${i}"`)}`}`;}
